import ctypes
import os
import subprocess
import numpy as np
from scipy import sparse
from scipy.sparse.linalg._eigen.arpack import _arpacklib
from scipy.sparse.linalg._eigen.arpack.arpack import _UnsymmetricArpackParams, ArpackError

_HERE = os.path.dirname(os.path.abspath(__file__))

_DFIELDS = ["tol", "getv0_rnorm0", "aitr_betaj", "aitr_rnorm1", "aitr_wnorm", "aup2_rnorm"]
_IFIELDS = ["which", "ido", "info", "bmat", "mode", "n", "ncv", "nev", "shift", "maxiter",
            "nconv", "iter", "np", "getv0_first", "getv0_iter", "getv0_itry", "getv0_orth",
            "aitr_iter", "aitr_j", "aitr_orth1", "aitr_orth2", "aitr_restart", "aitr_step3",
            "aitr_step4", "aitr_ierr", "aup2_initv", "aup2_iter", "aup2_getv0", "aup2_cnorm",
            "aup2_kplusp", "aup2_nev", "aup2_nev0", "aup2_np0", "aup2_numcnv", "aup2_update",
            "aup2_ushift"]


class _State(ctypes.Structure):
    # Mirrors the C state struct used by scipy's ARNAUD (offsets verified from the binary).
    _fields_ = [(f, ctypes.c_double) for f in _DFIELDS] + [(f, ctypes.c_int) for f in _IFIELDS]


_DRIVER_C = r'''
#include <string.h>
typedef void (*naupd_t)(void*, double*, double*, int, int*, double*, double*);
int run_loop(naupd_t f, void* st, int ido_off, double* resid, double* v, int ldv,
             int* ipntr, double* workd, double* workl,
             int n, const int* indptr, const int* indices, const double* data)
{
    for (;;) {
        f(st, resid, v, ldv, ipntr, workd, workl);
        int ido = *(int*)((char*)st + ido_off);
        if (ido == 1 || ido == 5) {
            const double* x = workd + ipntr[0];
            double* y = workd + ipntr[1];
            for (int i = 0; i < n; i++) {
                double s = 0.0;
                for (int jj = indptr[i]; jj < indptr[i+1]; jj++)
                    s += data[jj] * x[indices[jj]];
                y[i] = s;
            }
        } else if (ido == 2) {
            memmove(workd + ipntr[1], workd + ipntr[0], sizeof(double) * n);
        } else {
            return ido;
        }
    }
}
'''


def _build_arpack(dst):
    # Accelerate's "$NEWLAPACK" dtrevc is ~5x slower than the legacy dtrevc_ for the
    # tiny Hessenberg matrices ARPACK uses, with identical results. Relink just that symbol.
    b = bytearray(open(_arpacklib.__file__, "rb").read())
    old = b"_dtrevc$NEWLAPACK\0"
    i = b.find(old)
    if i < 0:
        raise RuntimeError("symbol not found")
    new = b"_dtrevc_"
    b[i:i + len(old)] = new + b"\0" * (len(old) - len(new))
    tmp = dst + ".tmp%d" % os.getpid()
    with open(tmp, "wb") as fh:
        fh.write(b)
    subprocess.run(["codesign", "-f", "-s", "-", tmp], check=True,
                   stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    os.replace(tmp, dst)


def _build_driver(dst):
    src = dst[:-3] + ".c"
    with open(src, "w") as fh:
        fh.write(_DRIVER_C)
    tmp = dst + ".tmp%d" % os.getpid()
    subprocess.run(["cc", "-O2", "-ffp-contract=off", "-shared", "-fPIC", "-o", tmp, src],
                   check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    os.replace(tmp, dst)


def _load():
    assert ctypes.sizeof(_State) == 0xc0
    lib = None
    p = os.path.join(_HERE, "fastarpack.so")
    try:
        if not os.path.exists(p):
            _build_arpack(p)
        lib = ctypes.CDLL(p)
        lib.ARNAUD_dnaupd
    except Exception:
        lib = ctypes.CDLL(_arpacklib.__file__)
    naupd = lib.ARNAUD_dnaupd
    drv = None
    try:
        d = os.path.join(_HERE, "arpdriver.so")
        if not os.path.exists(d):
            _build_driver(d)
        drv = ctypes.CDLL(d).run_loop
        vp = ctypes.c_void_p
        drv.argtypes = [vp, vp, ctypes.c_int, vp, vp, ctypes.c_int, vp, vp, vp,
                        ctypes.c_int, vp, vp, vp]
        drv.restype = ctypes.c_int
    except Exception:
        drv = None
    return naupd, drv


try:
    _dnaupd, _driver = _load()
    _OK = True
except Exception:
    _OK = False

_IDO_OFF = _State.ido.offset


class Solver:
    def solve(self, problem, **kwargs):
        A = problem["matrix"]
        k = problem["k"]
        N = A.shape[0]
        ncv = max(2 * k + 1, 20)
        v0 = np.ones(N, dtype=A.dtype)
        if not (_OK and _driver is not None and sparse.issparse(A) and A.format == "csr"
                and A.dtype == np.float64 and A.shape[0] == A.shape[1]):
            w, v = sparse.linalg.eigs(A, k=k, v0=v0, maxiter=N * 200, ncv=ncv)
        else:
            params = _UnsymmetricArpackParams(N, k, 'd', lambda x: A @ x, 1,
                                              None, None, None, ncv, v0,
                                              N * 200, 'LM', 0, None)
            ad = params.arpack_dict
            st = _State()
            for f in _DFIELDS + _IFIELDS:
                setattr(st, f, ad[f])
            V = np.asfortranarray(params.v)
            params.v = V
            resid, ipntr, workd, workl = params.resid, params.ipntr, params.workd, params.workl
            indptr = np.ascontiguousarray(A.indptr, dtype=np.int32)
            indices = np.ascontiguousarray(A.indices, dtype=np.int32)
            data = np.ascontiguousarray(A.data, dtype=np.float64)
            naupd_addr = ctypes.cast(_dnaupd, ctypes.c_void_p).value
            while True:
                ido = _driver(naupd_addr, ctypes.addressof(st), _IDO_OFF,
                              resid.ctypes.data, V.ctypes.data, N, ipntr.ctypes.data,
                              workd.ctypes.data, workl.ctypes.data, N,
                              indptr.ctypes.data, indices.ctypes.data, data.ctypes.data)
                if ido == 4:
                    resid[:] = params.rng.uniform(low=-1.0, high=1.0, size=[N])
                    continue
                break
            for fn in _DFIELDS + _IFIELDS:
                ad[fn] = getattr(st, fn)
            params.converged = True
            if st.info == 1:
                params._raise_no_convergence()
            elif st.info != 0:
                raise ArpackError(st.info, infodict=params.iterate_infodict)
            w, v = params.extract(True)
        order = sorted(range(len(w)), key=lambda i: -abs(w[i]))
        return [v[:, i] for i in order]

