def lazy_slots(path):
    b=open(path,'rb').read()
    magic,cpu,sub,ft,ncmds,size,flags,res=struct.unpack_from('<IiiIIIII',b,0)
    assert magic==0xfeedfacf
    off=32; secs=[]; symtab=dysym=None
    for _ in range(ncmds):
        cmd,cs=struct.unpack_from('<II',b,off)
        if cmd==0x19:
            segname=b[off+8:off+24].rstrip(b'\0'); nsects=struct.unpack_from('<I',b,off+64)[0]
            so=off+72
            for i in range(nsects):
                sn=b[so:so+16].rstrip(b'\0'); addr,sz,fo,al,ro,nr,fl,r1,r2,r3=struct.unpack_from('<QQIIIIIIII',b,so+32)
                secs.append((sn,addr,sz,fl,r1)); so+=80
        elif cmd==2: symtab=struct.unpack_from('<IIII',b,off+8)
        elif cmd==0xb: dysym=struct.unpack_from('<18I',b,off+8)
        off+=cs
    symoff,nsyms,stroff,strsize=symtab
    indoff,nind=dysym[12],dysym[13]
    def name(i):
        sx=struct.unpack_from('<I',b,symoff+16*i)[0]; e=b.index(b'\0',stroff+sx); return b[stroff+sx:e].decode()
    def value(nm):
        for i in range(nsyms):
            if name(i)==nm: return struct.unpack_from('<Q',b,symoff+16*i+8)[0]
    out={}
    for sn,addr,sz,fl,r1 in secs:
        if (fl&0xff) in (6,7):  # non-lazy / lazy symbol pointers
            for j in range(sz//8):
                idx=struct.unpack_from('<I',b,indoff+4*(r1+j))[0]
                if idx & 0xC0000000: continue
                out[name(idx)]=addr+8*j
    return out,value
