#include <string.h>
#include <pthread.h>
#include <stdatomic.h>
#include <immintrin.h>
typedef void (*naupd_t)(void*, double*, double*, int, int*, double*, double*);
#define MAXT 16
typedef struct {
    const int* indptr; const int* indices; const double* data;
    const double* x; double* y;
    int bounds[MAXT+1];
    int nt;
    _Atomic int gen;
    _Atomic int done;
    _Atomic int stop;
} pool_t;
typedef struct { pool_t* p; int id; } warg_t;

static inline void rows(const pool_t* p, int r0, int r1) {
    const int* ip = p->indptr; const int* ix = p->indices; const double* d = p->data;
    const double* x = p->x; double* y = p->y;
    for (int i = r0; i < r1; i++) {
        double s = 0.0;
        for (int j = ip[i]; j < ip[i+1]; j++) s += d[j] * x[ix[j]];
        y[i] = s;
    }
}
static void* worker(void* a) {
    warg_t* w = (warg_t*)a; pool_t* p = w->p; int id = w->id;
    int seen = 0;
    for (;;) {
        int g;
        while ((g = atomic_load_explicit(&p->gen, memory_order_acquire)) == seen) {
            if (atomic_load_explicit(&p->stop, memory_order_relaxed)) return 0;
            _mm_pause();
        }
        seen = g;
        rows(p, p->bounds[id], p->bounds[id+1]);
        atomic_fetch_add_explicit(&p->done, 1, memory_order_release);
    }
}
int run_loop(naupd_t f, void* st, int ido_off, double* resid, double* v, int ldv,
             int* ipntr, double* workd, double* workl,
             int n, const int* indptr, const int* indices, const double* data, int nt)
{
    pool_t p; pthread_t th[MAXT]; warg_t wa[MAXT];
    if (nt < 1) nt = 1; if (nt > MAXT) nt = MAXT;
    p.indptr = indptr; p.indices = indices; p.data = data; p.nt = nt;
    atomic_init(&p.gen, 0); atomic_init(&p.done, 0); atomic_init(&p.stop, 0);
    long long nnz = indptr[n] - indptr[0];
    int r = 0;
    p.bounds[0] = 0;
    for (int t = 1; t < nt; t++) {
        long long target = indptr[0] + nnz * t / nt;
        while (r < n && indptr[r] < target) r++;
        p.bounds[t] = r;
    }
    p.bounds[nt] = n;
    int started = 0;
    for (int t = 1; t < nt; t++) {
        wa[t].p = &p; wa[t].id = t;
        if (pthread_create(&th[t], 0, worker, &wa[t]) != 0) break;
        started = t;
    }
    if (started != nt - 1) {  /* fallback: single thread */
        atomic_store(&p.stop, 1);
        for (int t = 1; t <= started; t++) pthread_join(th[t], 0);
        nt = 1; p.bounds[1] = n; started = 0;
    }
    int ido, gen = 0;
    for (;;) {
        f(st, resid, v, ldv, ipntr, workd, workl);
        ido = *(int*)((char*)st + ido_off);
        if (ido == 1 || ido == 5) {
            p.x = workd + ipntr[0]; p.y = workd + ipntr[1];
            if (nt > 1) {
                atomic_store_explicit(&p.done, 0, memory_order_relaxed);
                atomic_store_explicit(&p.gen, ++gen, memory_order_release);
                rows(&p, p.bounds[0], p.bounds[1]);
                while (atomic_load_explicit(&p.done, memory_order_acquire) != nt - 1) _mm_pause();
            } else {
                rows(&p, 0, n);
            }
        } else if (ido == 2) {
            memmove(workd + ipntr[1], workd + ipntr[0], sizeof(double) * n);
        } else break;
    }
    atomic_store(&p.stop, 1);
    for (int t = 1; t <= started; t++) pthread_join(th[t], 0);
    return ido;
}
