/* Rows grouped by equal length L. For group g: rows[g0..g1), entries stored row-major contiguous.
   4 rows processed simultaneously, each with sequential (original-order) summation. */
void mvb(int ng, const int* glen, const int* gstart, const int* rows, const int* idx, const double* val,
         const double* x, double* y, int reps)
{
  for (int r = 0; r < reps; r++) {
    const int* ix = idx; const double* d = val;
    for (int g = 0; g < ng; g++) {
      int L = glen[g], a = gstart[g], b = gstart[g+1];
      int i = a;
      for (; i + 3 < b; i += 4) {
        const int *i0 = ix, *i1 = ix + L, *i2 = ix + 2*L, *i3 = ix + 3*L;
        const double *d0 = d, *d1 = d + L, *d2 = d + 2*L, *d3 = d + 3*L;
        double s0 = 0.0, s1 = 0.0, s2 = 0.0, s3 = 0.0;
        for (int k = 0; k < L; k++) {
          s0 += d0[k] * x[i0[k]]; s1 += d1[k] * x[i1[k]];
          s2 += d2[k] * x[i2[k]]; s3 += d3[k] * x[i3[k]];
        }
        y[rows[i]] = s0; y[rows[i+1]] = s1; y[rows[i+2]] = s2; y[rows[i+3]] = s3;
        ix += 4*L; d += 4*L;
      }
      for (; i < b; i++) {
        double s = 0.0;
        for (int k = 0; k < L; k++) s += d[k] * x[ix[k]];
        y[rows[i]] = s; ix += L; d += L;
      }
    }
  }
}
