void my_dcopy(const int* n, const double* x, const int* incx, double* y, const int* incy) {
    int N = *n, ix = *incx, iy = *incy;
    if (N <= 0) return;
    if (ix == 1 && iy == 1) { memmove(y, x, sizeof(double) * N); return; }
    int px = ix < 0 ? (1 - N) * ix : 0, py = iy < 0 ? (1 - N) * iy : 0;
    for (int i = 0; i < N; i++) { y[py] = x[px]; px += ix; py += iy; }
}
void my_dscal(const int* n, const double* a, double* x, const int* incx) {
    int N = *n, ix = *incx; double A = *a;
    if (N <= 0 || ix <= 0) return;
    for (int i = 0, p = 0; i < N; i++, p += ix) x[p] = A * x[p];
}
