#include <math.h>
/* variant flags: fma usage */
#ifndef FMA
#define FMA 0
#endif
static inline double madd(double acc, double a, double b){
#if FMA
  return fma(a,b,acc);
#else
  return acc + a*b;
#endif
}
void my_dlarf(const char* side, const int* M, const int* N, const double* v, const int* incv,
              const double* tau, double* C, const int* LDC, double* work)
{
  int m=*M, n=*N, ldc=*LDC, iv=*incv; double t=*tau;
  int left = (*side=='L' || *side=='l');
  int lastv=0, lastc=0;
  if (t != 0.0) {
    lastv = left ? m : n;
    int i = iv>0 ? 1+(lastv-1)*iv : 1;
    while (lastv>0 && v[i-1]==0.0) { lastv--; i -= iv; }
    if (left) { /* iladlc(lastv, n, C) */
      if (n==0) lastc=0;
      else if (C[(n-1)*ldc]!=0.0 || C[(lastv-1)+(n-1)*ldc]!=0.0) lastc=n;
      else { for (lastc=n; lastc>=1; lastc--) { int nz=0; for (int r=0;r<lastv;r++) if (C[r+(lastc-1)*ldc]!=0.0){nz=1;break;} if(nz) break; } }
    } else { /* iladlr(m, lastv, C) */
      if (m==0) lastc=0;
      else if (C[m-1]!=0.0 || C[(m-1)+(lastv-1)*ldc]!=0.0) lastc=m;
      else { lastc=0; for (int j=0;j<lastv;j++){ int i2=m; while (i2>=1 && C[(i2>1?i2:1)-1+j*ldc]==0.0 && i2>=1) i2--; if(i2>lastc) lastc=i2; } }
    }
  }
  if (lastv<=0 || lastc<=0) return;
  if (iv!=1) { /* not expected */ return; }
  if (left) {
    for (int j=0;j<lastc;j++){ double s=0.0; for(int i=0;i<lastv;i++) s=madd(s,C[i+j*ldc],v[i]); work[j]=s; }
    for (int j=0;j<lastc;j++){ double tmp=-t*work[j]; if(tmp!=0.0) for(int i=0;i<lastv;i++) C[i+j*ldc]=madd(C[i+j*ldc],v[i],tmp); }
  } else {
    for (int i=0;i<lastc;i++) work[i]=0.0;
    for (int j=0;j<lastv;j++){ double tmp=v[j]; if(tmp!=0.0) for(int i=0;i<lastc;i++) work[i]=madd(work[i],tmp,C[i+j*ldc]); }
    for (int j=0;j<lastv;j++){ double tmp=-t*v[j]; if(tmp!=0.0) for(int i=0;i<lastc;i++) C[i+j*ldc]=madd(C[i+j*ldc],work[i],tmp); }
  }
}
