#include <string.h>
#include <stdint.h>
typedef void (*naupd_t)(void*, double*, double*, int, int*, double*, double*);
int run_loop16(naupd_t f, void* st, int ido_off, double* resid, double* v, int ldv,
             int* ipntr, double* workd, double* workl,
             int n, const int* indptr, const uint16_t* indices, const double* data)
{
    for (;;) {
        f(st, resid, v, ldv, ipntr, workd, workl);
        int ido = *(int*)((char*)st + ido_off);
        if (ido == 1 || ido == 5) {
            const double* x = workd + ipntr[0];
            double* y = workd + ipntr[1];
            int j = indptr[0];
            for (int i = 0; i < n; i++) {
                int e = indptr[i+1];
                double s = 0.0;
                for (; j < e; j++) s += data[j] * x[indices[j]];
                y[i] = s;
            }
        } else if (ido == 2) {
            memmove(workd + ipntr[1], workd + ipntr[0], sizeof(double) * n);
        } else {
            return ido;
        }
    }
}
